/* PaKuWord – polska paczka dzienna 2026-11-28: nowa dziedzina Fizyka (30) + 30 haseł w istniejących dziedzinach (ast, med, law, gen, psy) */
window.PW_CONTENT = window.PW_CONTENT || {};
window.PW_CONTENT.pl = (window.PW_CONTENT.pl || []).concat([
/* ---------- FIZYKA ---------- */
{id:"phy_physics",cat:"phy",t:"Fizyka",
 s:"Nauka o materii, energii, ruchu i siłach, które je ze sobą łączą.",
 l:"Fizyka szuka najprostszych praw stojących za wszystkim, co się dzieje – od piłki toczącej się z górki po światło przemierzające Wszechświat. Fizycy wykonują dokładne pomiary, opisują prawidłowości za pomocą matematyki i sprawdzają swoje pomysły w doświadczeniach. Na fizyce opierają się inne nauki: chemia korzysta z jej wiedzy o atomach, a technika z praw ruchu i elektryczności. Telefony, lodówki czy rowery działają dzięki zasadom, które odkryli fizycy.",
 x:"Na fizyce mierzyliśmy wahadło i okazało się, że dłuższe waha się wolniej.",
 f:"Nazwa pochodzi od greckiego słowa physis, czyli natura.",
 js:"Nauka o tym, jak rzeczy się poruszają, pchają, ciągną, świecą i brzmią.",
 jl:"Fizyka zadaje wielkie pytania. Dlaczego rzeczy spadają? Jak magnes trzyma się lodówki? Czemu w dzień niebo jest jasne? Fizycy szukają odpowiedzi, robiąc doświadczenia i bardzo dokładnie wszystko mierząc.",
 jx:"Na lekcji fizyki sprawdzaliśmy, który papierowy samolot poleci najdalej."},
{id:"phy_force",cat:"phy",t:"Siła",
 s:"Pchnięcie lub pociągnięcie, które może zmienić ruch ciała albo jego kształt.",
 l:"Siła zawsze działa w określonym kierunku i ma swoją wartość, dlatego fizycy rysują ją jako strzałkę. Siła może wprawić nieruchome ciało w ruch, przyspieszyć je, zahamować, skręcić albo zgnieść. Zwykle działa kilka sił naraz: książkę na stole Ziemia przyciąga w dół, a stół pcha ją w górę, i ponieważ te siły się równoważą, książka leży spokojnie. Siłę mierzy się w niutonach, a w szkole często siłomierzem, czyli sprężyną ze skalą.",
 x:"Wiatr działał na parasol z taką siłą, że wywinął go na drugą stronę.",
 f:"Siła o wartości około jednego niutona to mniej więcej tyle, ile czujesz, trzymając na dłoni małe jabłko.",
 js:"Pchnięcie albo pociągnięcie.",
 jl:"Kiedy kopiesz piłkę, popychasz ją siłą i piłka leci. Kiedy otwierasz szufladę, ciągniesz ją siłą. Siły mogą sprawić, że coś ruszy, zatrzyma się, skręci albo zmieni kształt – jak plastelina, którą ściskasz w dłoni.",
 jx:"Musiałem użyć dużej siły, żeby odkręcić słoik z dżemem."},
{id:"phy_gravity",cat:"phy",t:"Grawitacja (ciążenie)",
 s:"Oddziaływanie, w którym każde ciało mające masę przyciąga każde inne.",
 l:"Grawitacja sprawia, że przedmioty spadają na ziemię, że stoimy na Ziemi i że Księżyc krąży wokół naszej planety. Im większa masa ciała, tym silniej przyciąga, a im dalej od niego, tym przyciąganie słabsze. Między zwykłymi przedmiotami grawitacja jest zbyt słaba, żebyśmy ją zauważyli, ale cała planeta czy gwiazda przyciąga bardzo mocno. W siedemnastym wieku Izaak Newton opisał ją prawem powszechnego ciążenia, a Albert Einstein wyjaśnił później jako zakrzywienie czasoprzestrzeni.",
 x:"Przez grawitację łyżka, która wypadła mi z ręki, z brzękiem uderzyła o podłogę.",
 f:"Na Księżycu przyciąganie jest około sześć razy słabsze niż na Ziemi, dlatego astronauci mogli tam skakać znacznie wyżej.",
 js:"Niewidzialne przyciąganie, przez które rzeczy spadają w dół.",
 jl:"Kiedy podskakujesz, zawsze wracasz na ziemię. To grawitacja przyciąga cię do Ziemi. Dzięki niej Księżyc krąży wokół Ziemi, a Ziemia wokół Słońca. Najmocniej przyciągają ogromne, ciężkie ciała, takie jak planety.",
 jx:"Grawitacja ściągnęła mi lody z wafelka prosto na chodnik."},
{id:"phy_mass_weight",cat:"phy",t:"Masa i ciężar",
 s:"Masa to ilość materii w ciele, a ciężar to siła, z jaką grawitacja przyciąga tę masę.",
 l:"Na co dzień używamy tych słów zamiennie, ale w fizyce to dwie różne wielkości. Masę mierzy się w kilogramach i jest taka sama bez względu na to, gdzie znajduje się ciało. Ciężar jest siłą, więc wyraża się go w niutonach, i zależy od tego, jak silna jest grawitacja. Astronauta ma tę samą masę na Ziemi i na Księżycu, ale na Księżycu waży znacznie mniej. Waga łazienkowa w rzeczywistości mierzy nacisk i przelicza go na kilogramy.",
 x:"Próbki skał mają na Marsie tę samą masę co na Ziemi, ale mniejszy ciężar.",
 f:"Do 2019 roku kilogram określał metalowy walec przechowywany pod Paryżem; dziś definiuje się go za pomocą stałej fizycznej zwanej stałą Plancka.",
 js:"Masa to ile czegoś jest, a ciężar to jak mocno przyciąga to Ziemia.",
 jl:"Twoja masa mówi, ile ciebie jest, i jest taka sama na Ziemi i na Księżycu. Ciężar mówi, jak mocno grawitacja ciągnie cię w dół. Na Księżycu grawitacja jest słabsza, więc ważyłbyś mniej, choć dalej byłbyś dokładnie tym samym sobą.",
 jx:"Na Księżycu mój plecak wydawałby się lżejszy, choć byłyby w nim te same książki."},
{id:"phy_energy",cat:"phy",t:"Energia",
 s:"Zdolność do wykonania pracy, na przykład poruszenia czegoś, ogrzania albo zaświecenia.",
 l:"Energia ma wiele postaci: energia ruchu, energia zmagazynowana w napiętej sprężynie albo w podniesionym ciężarze, ciepło, światło, dźwięk, energia chemiczna w jedzeniu i paliwie oraz energia elektryczna. Nie znika, gdy ją zużywamy, tylko zamienia się z jednej postaci w inną. Latarka zamienia energię chemiczną baterii na światło i trochę ciepła. Energię mierzy się w dżulach, których nazwa pochodzi od angielskiego fizyka Jamesa Prescotta Joule’a.",
 x:"Turbina wiatrowa zamienia energię poruszającego się powietrza na energię elektryczną.",
 f:"James Prescott Joule, od którego nazwiska pochodzi jednostka energii, prowadził też rodzinny browar w okolicach Manchesteru.",
 js:"To, dzięki czemu rzeczy się ruszają, grzeją, świecą albo brzmią.",
 jl:"Potrzebujesz energii, żeby biegać, skakać i myśleć, a dostajesz ją z jedzenia. Samochód bierze energię z paliwa albo z akumulatora. Lampa zamienia energię elektryczną na światło. Energia ciągle zmienia się z jednej postaci w drugą, trochę jak woda przelewana z kubka do kubka.",
 jx:"Po śniadaniu miałam mnóstwo energii na wycieczkę szkolną."},
{id:"phy_conservation_energy",cat:"phy",t:"Zasada zachowania energii",
 s:"Prawo mówiące, że energia nie powstaje z niczego i nie znika, a jedynie zmienia postać.",
 l:"Jeśli zsumujemy całą energię w układzie zamkniętym przed jakimś zdarzeniem i po nim, wynik będzie taki sam. Gdy piłka spada, jej energia położenia zamienia się w energię ruchu, a po uderzeniu w ziemię – w dźwięk i odrobinę ciepła. Żadna maszyna nie oddaje więcej energii, niż pobiera, a część zawsze zamienia się w ciepło, które trudno wykorzystać. Dlatego perpetuum mobile, czyli urządzenie działające wiecznie bez zasilania, jest niemożliwe.",
 x:"Z zasady zachowania energii wynika, że huśtawka bez popychania nie wzniesie się wyżej niż punkt, z którego ją puściłeś.",
 f:"W 1918 roku matematyczka Emmy Noether wykazała, że zasada zachowania energii wynika z tego, że prawa fizyki nie zmieniają się w czasie.",
 js:"Energia nigdy nie znika, tylko zamienia się w inny rodzaj.",
 jl:"Energia jest jak czarodziej, który zmienia kostiumy, ale nigdy nie znika. Kiedy zjeżdżasz na sankach z górki, energia bycia wysoko zamienia się w prędkość. Kiedy się zatrzymujesz, zamienia się w odrobinę ciepła i szum śniegu. Razem jest jej zawsze tyle samo.",
 jx:"Pani powiedziała, że energia mojego zjazdu na sankach nie zniknęła, tylko zamieniła się w ciepło i hałas."},
{id:"phy_friction",cat:"phy",t:"Tarcie",
 s:"Siła przeciwdziałająca przesuwaniu się lub toczeniu jednej powierzchni po drugiej.",
 l:"Tarcie pojawia się zawsze, gdy powierzchnie się stykają i próbują przesunąć względem siebie, bo nawet gładko wyglądające powierzchnie są w mikroskali chropowate. Tarcie spowalnia ruch i zamienia część energii ruchu na ciepło, dlatego pocieranie dłoni je rozgrzewa. Często jest bardzo przydatne: bez niego buty by się ślizgały, opony nie trzymałyby się drogi, a węzły same by się rozwiązywały. Niepotrzebne tarcie zmniejsza się smarem, łożyskami albo gładkimi materiałami.",
 x:"Nowe opony mają większe tarcie, więc rower nie wpada w poślizg na mokrej jezdni.",
 f:"Leonardo da Vinci badał tarcie w swoich notatkach i zauważył, że nie zależy ono od wielkości stykających się powierzchni; tę zasadę ponownie odkrył Guillaume Amontons w 1699 roku.",
 js:"Siła, przez którą rzeczy się ocierają i zwalniają.",
 jl:"Spróbuj popchnąć autko po dywanie, a potem po gładkiej podłodze. Na dywanie szybko się zatrzyma, bo jest tam większe tarcie. Dzięki tarciu twoje buty trzymają się ziemi i się nie ślizgasz. Kiedy pocierasz dłonie, tarcie je rozgrzewa.",
 jx:"Ślizgałem się w skarpetkach po błyszczącej podłodze, bo tarcie było bardzo małe."},
{id:"phy_inertia",cat:"phy",t:"Bezwładność",
 s:"Właściwość ciał polegająca na tym, że bez działania siły pozostają w spoczynku albo poruszają się ruchem jednostajnym prostoliniowym.",
 l:"Ciało nie potrzebuje siły, żeby się poruszać – potrzebuje jej, żeby zmienić swój ruch. Na Ziemi poruszające się przedmioty zwalniają, bo działa na nie tarcie i opór powietrza. Bezwładność tłumaczy, dlaczego pasażerowie lecą do przodu, gdy autobus gwałtownie hamuje: ich ciała dalej się poruszają, choć autobus zwalnia. Im większa masa, tym większa bezwładność, więc załadowaną ciężarówkę znacznie trudniej rozpędzić i zatrzymać niż rower. Pasy bezpieczeństwa istnieją właśnie z powodu bezwładności.",
 x:"Kiedy tramwaj ostro zahamował, bezwładność pchnęła stojących pasażerów do przodu.",
 f:"Galileusz, badając kulki staczające się po pochylniach, doszedł do idei bezwładności jeszcze przed Newtonem.",
 js:"Rzeczy lubią dalej robić to, co już robią.",
 jl:"Jeśli piłka leży, będzie leżeć, dopóki ktoś jej nie kopnie. Jeśli się toczy, chce się dalej toczyć. To się nazywa bezwładność. Gdy samochód nagle hamuje, twoje ciało chce dalej jechać do przodu. Dlatego zawsze zapinamy pasy.",
 jx:"Kiedy autobus stanął, bezwładność sprawiła, że moja butelka z wodą potoczyła się do przodu."},
{id:"phy_velocity",cat:"phy",t:"Szybkość i prędkość",
 s:"Szybkość mówi, jak szybko coś się porusza, a prędkość dodatkowo określa kierunek tego ruchu.",
 l:"Szybkość mówi, jaką drogę ciało pokonuje w określonym czasie, na przykład pięćdziesiąt kilometrów na godzinę. Prędkość to wielkość wektorowa, więc ma też kierunek, na przykład pięćdziesiąt kilometrów na godzinę na północ. Ta różnica ma znaczenie: samochód jadący po rondzie ze stałą szybkością ciągle zmienia prędkość, bo zmienia kierunek. W fizyce zwykle podaje się je w metrach na sekundę. W mowie potocznej oba słowa często używa się zamiennie.",
 x:"Szybkość pociągu się nie zmieniła, ale na zakręcie zmieniła się jego prędkość.",
 f:"Światło w próżni pokonuje prawie trzysta tysięcy kilometrów na sekundę, a dźwięk w powietrzu – tylko około trzystu czterdziestu metrów.",
 js:"Jak szybko coś się porusza i w którą stronę.",
 jl:"Szybkość mówi, jak szybko się poruszasz – wolno jak ślimak albo szybko jak gepard. Prędkość mówi jeszcze, dokąd zmierzasz, na przykład szybko w stronę bramy szkoły. Gdy biegasz w kółko z tą samą szybkością, twój kierunek ciągle się zmienia.",
 jx:"Na boisku zmierzyłem stoperem, z jaką szybkością biegam."},
{id:"phy_acceleration",cat:"phy",t:"Przyspieszenie",
 s:"Wielkość opisująca, jak szybko zmienia się prędkość: przy przyspieszaniu, hamowaniu lub skręcaniu.",
 l:"Kiedy samochód rusza i w kilka sekund osiąga pięćdziesiąt kilometrów na godzinę, ma przyspieszenie. Hamowanie to także przyspieszenie, tylko skierowane przeciwnie do ruchu, a skręcanie również, bo zmienia się kierunek. Przyspieszenie wywołuje siła, a ta sama siła nadaje lekkiemu ciału większe przyspieszenie niż ciężkiemu. Przy powierzchni Ziemi spadające ciała, jeśli opór powietrza jest mały, przyspieszają o około dziewięć i osiem dziesiątych metra na sekundę w każdej sekundzie.",
 x:"Przyspieszenie kolejki górskiej wcisnęło nas w siedzenia.",
 f:"W 1971 roku astronauta misji Apollo 15 David Scott upuścił na Księżycu, gdzie nie ma powietrza, młotek i piórko – i oba uderzyły w grunt w tej samej chwili.",
 js:"Gdy coś jedzie coraz szybciej, coraz wolniej albo skręca.",
 jl:"Kiedy zaczynasz pedałować i jedziesz coraz szybciej, przyspieszasz. Kiedy naciskasz hamulec i zwalniasz, to też jest rodzaj przyspieszenia. Nawet skręcanie się liczy, bo zmienia się kierunek jazdy.",
 jx:"Wyścigówka miała tak duże przyspieszenie, że zniknęła w mgnieniu oka."},
{id:"phy_newton_laws",cat:"phy",t:"Zasady dynamiki Newtona",
 s:"Trzy podstawowe prawa, sformułowane przez Izaaka Newtona, które opisują, jak siły wpływają na ruch ciał.",
 l:"Pierwsza zasada mówi, że ciało pozostaje w spoczynku albo porusza się ruchem jednostajnym prostoliniowym, jeśli nie działa na nie żadna siła lub siły się równoważą. Druga mówi, że siła nadaje ciału przyspieszenie, a im większa masa, tym większej siły potrzeba do tego samego przyspieszenia. Trzecia mówi, że siły występują parami: gdy na coś naciskasz, ono naciska na ciebie tak samo mocno w przeciwną stronę. Tych zasad wciąż używa się przy projektowaniu mostów, samochodów i lotów kosmicznych.",
 x:"Rakieta leci dzięki trzeciej zasadzie dynamiki: wyrzuca gorące gazy w dół, a one pchają ją w górę.",
 f:"Newton ogłosił te zasady w 1687 roku w napisanym po łacinie dziele Philosophiae Naturalis Principia Mathematica, nazywanym w skrócie Principiami.",
 js:"Trzy zasady o tym, jak pchnięcia i pociągnięcia poruszają rzeczy.",
 jl:"Izaak Newton zauważył trzy reguły. Rzeczy stoją albo jadą dalej, dopóki ktoś ich nie popchnie lub nie pociągnie. Mocniejsze pchnięcie bardziej je rozpędza. A kiedy coś pchasz, ono pcha ciebie – jak wtedy, gdy odpychasz się od brzegu basenu.",
 jx:"Kiedy na wrotkach odepchnąłem kolegę, obaj potoczyliśmy się do tyłu, zupełnie jak w trzeciej zasadzie dynamiki."},
{id:"phy_atom",cat:"phy",t:"Atom",
 s:"Najmniejsza cząstka pierwiastka chemicznego, zbudowana z jądra i krążących wokół niego elektronów.",
 l:"Wszystko wokół nas składa się z atomów. Każdy atom ma bardzo małe, ciężkie jądro złożone z protonów i neutronów, otoczone znacznie lżejszymi elektronami. Liczba protonów decyduje o tym, jaki to pierwiastek: jeden ma wodór, sześć węgiel, osiem tlen. Atomy są tak małe, że miliony zmieściłyby się na szerokości kropki kończącej to zdanie. Większą część atomu stanowi pusta przestrzeń.",
 x:"Cząsteczka wody składa się z dwóch atomów wodoru połączonych z jednym atomem tlenu.",
 f:"Nazwa pochodzi od greckiego atomos, czyli niepodzielny, bo starożytni myśliciele wyobrażali sobie atomy jako najmniejsze cząstki, których nie da się podzielić; dziś wiemy, że da się je rozbić.",
 js:"Malutki klocek, z którego wszystko jest zbudowane.",
 jl:"Wszystko wokół ciebie – ławka, powietrze, a nawet ty – składa się z malutkich cząstek zwanych atomami. Są o wiele za małe, żeby je zobaczyć, nawet przez zwykły mikroskop. Są różne rodzaje atomów, jak klocki w różnych kolorach, i łączą się ze sobą w różne rzeczy.",
 jx:"Pani powiedziała, że ołówek w mojej ręce składa się z miliardów miliardów atomów."},
{id:"phy_electron",cat:"phy",t:"Elektron",
 s:"Bardzo mała cząstka o ujemnym ładunku elektrycznym, która porusza się wokół jądra atomu.",
 l:"Elektrony są dużo lżejsze od protonów i neutronów w jądrze. Utrzymuje je przy jądrze przyciąganie elektryczne, bo ładunki przeciwne się przyciągają. Elektrony mogą przechodzić z jednego atomu do drugiego, a ich uporządkowany ruch w przewodzie to właśnie prąd elektryczny. Od rozmieszczenia elektronów w atomie zależy, jak reaguje on chemicznie. Elektron odkrył w 1897 roku brytyjski fizyk Joseph John Thomson.",
 x:"Gdy pocierasz balon o sweter, elektrony przechodzą na balon i przykleja się on do ściany.",
 f:"Nazwa pochodzi od greckiego słowa oznaczającego bursztyn, bo już w starożytności zauważono, że potarty bursztyn przyciąga drobne przedmioty, na przykład piórka.",
 js:"Malutka cząstka atomu, która nosi elektryczność.",
 jl:"W każdym atomie są maleńkie cząstki zwane elektronami, które krążą wokół środka. Są tak małe, że nikt ich nie zobaczy. Kiedy dużo elektronów płynie przez przewód, mamy prąd, który może zapalić lampkę.",
 jx:"Potarłam balon o włosy i przez elektrony włosy stanęły mi dęba."},
{id:"phy_electric_current",cat:"phy",t:"Prąd elektryczny",
 s:"Uporządkowany przepływ ładunków elektrycznych, najczęściej elektronów, na przykład w przewodzie.",
 l:"Prąd płynie tylko wtedy, gdy istnieje zamknięta droga, czyli obwód, i coś, co przesuwa ładunki, na przykład bateria. Materiały, które łatwo przewodzą prąd, jak miedź, to przewodniki, a te, które go nie przepuszczają, jak plastik i guma, to izolatory. Natężenie prądu mierzy się w amperach, nazwanych od francuskiego uczonego André-Marie Ampère’a. Włącznik działa, zamykając lub otwierając przerwę w obwodzie.",
 x:"Żarówka zaświeciła, gdy tylko zamknęliśmy obwód i prąd mógł popłynąć.",
 f:"Na schematach prąd płynie od plusa do minusa, ale elektrony poruszają się w przeciwną stronę – kierunek umówiono się oznaczać, zanim odkryto elektron.",
 js:"Elektryczność płynąca przez przewód.",
 jl:"Prąd elektryczny jest jak rzeka elektryczności płynąca przez przewód. Może płynąć tylko wtedy, gdy droga tworzy całe kółko: od baterii, przez lampkę i z powrotem. Prąd z gniazdka jest bardzo niebezpieczny, dlatego doświadczenia robimy tylko z małymi bateriami.",
 jx:"Kiedy podłączyłam ostatni kabelek, prąd popłynął i brzęczyk zapiszczał."},
{id:"phy_voltage",cat:"phy",t:"Napięcie elektryczne",
 s:"Wielkość opisująca, jak mocno źródło „popycha” ładunki w obwodzie; mierzy się ją w woltach.",
 l:"Napięcie, nazywane też różnicą potencjałów, mówi, ile energii przenosi każda porcja ładunku między dwoma punktami. Większe napięcie może przepchnąć większy prąd przez to samo urządzenie. Mała bateria daje około półtora wolta, akumulator samochodowy około dwunastu, a gniazdka w domach w Polsce i w całej Europie – około dwustu trzydziestu woltów, co jest groźne dla życia. Jednostka nosi imię włoskiego uczonego Alessandra Volty.",
 x:"Zanim podłączysz laptopa kupionego za granicą, sprawdź, na jakie napięcie jest zasilacz.",
 f:"W 1800 roku Alessandro Volta zbudował pierwszą baterię elektryczną – stos krążków z cynku i miedzi przełożonych tkaniną nasączoną słoną wodą.",
 js:"Jak mocno elektryczność jest pchana przez przewód.",
 jl:"Napięcie jest jak ciśnienie, które pcha wodę w wężu ogrodowym. Mała bateria pcha delikatnie, akurat tyle, ile trzeba dla latarki albo zabawki. Gniazdko w ścianie pcha bardzo mocno i może zrobić krzywdę. Nigdy niczego do niego nie wkładaj.",
 jx:"Mój pilot potrzebuje dwóch małych baterii o niskim napięciu."},
{id:"phy_magnetism",cat:"phy",t:"Magnetyzm",
 s:"Zjawisko wywoływane przez magnesy i poruszające się ładunki, polegające na przyciąganiu lub odpychaniu niektórych materiałów.",
 l:"Każdy magnes ma dwa bieguny: północny i południowy. Bieguny różnoimienne się przyciągają, a jednoimienne odpychają. Magnesy mocno przyciągają żelazo, nikiel i kobalt, a prawie wcale papier, drewno czy większość innych metali. Elektryczność i magnetyzm są ze sobą ściśle związane: prąd w przewodzie wytwarza pole magnetyczne i na tym opiera się działanie silników elektrycznych i głośników. Sama Ziemia zachowuje się jak olbrzymi magnes, dlatego igła kompasu wskazuje mniej więcej północ.",
 x:"Dzięki magnetyzmowi oddzieliliśmy stalowe spinacze od plastikowych koralików.",
 f:"Pole magnetyczne Ziemi wielokrotnie w jej dziejach zmieniało kierunek na przeciwny; ostatnie pełne odwrócenie nastąpiło około siedmiuset osiemdziesięciu tysięcy lat temu.",
 js:"Niewidzialna siła, przez którą magnesy się przyciągają albo odpychają.",
 jl:"Magnes potrafi przyciągać niektóre metalowe rzeczy, na przykład spinacze albo drzwi lodówki. Jeśli trzymasz dwa magnesy odpowiednio, przyskakują do siebie. Odwróć jeden – i zaczną się odpychać. Kompas działa, bo Ziemia jest jak wielki magnes.",
 jx:"Zebrałem magnesem wszystkie szpilki, które spadły na podłogę."},
{id:"phy_wave",cat:"phy",t:"Fala",
 s:"Zaburzenie, które przenosi energię z miejsca na miejsce, nie przenosząc samej materii.",
 l:"Kiedy wrzucisz kamień do stawu, rozchodzą się zmarszczki, ale sama woda w większości porusza się tylko w górę i w dół w tym samym miejscu. Jako fale rozchodzą się dźwięk, światło, sygnały radiowe i drgania podczas trzęsienia ziemi. Fale opisuje się długością, czyli odległością od jednego grzbietu do następnego, i częstotliwością, czyli liczbą grzbietów mijających dany punkt w ciągu sekundy, mierzoną w hercach. Fale mogą się odbijać, załamywać i uginać na przeszkodach.",
 x:"Fale od przepływającej motorówki rozkołysały nasz kajak.",
 f:"Dobrze pokazuje to meksykańska fala na stadionie: fala obiega trybuny, choć każdy kibic zostaje na swoim miejscu.",
 js:"Drganie, które wędruje i niesie energię.",
 jl:"Wrzuć kamyk do kałuży i popatrz, jak rozchodzą się kółka. To są fale. Woda nigdzie nie ucieka, tylko podskakuje w górę i w dół, a fala wędruje dalej. Dźwięk i światło też są falami, choć nie widzimy, jak falują.",
 jx:"Zrobiliśmy falę długą skakanką, machając jednym jej końcem."},
{id:"phy_sound",cat:"phy",t:"Dźwięk",
 s:"Drgania rozchodzące się w powietrzu, wodzie lub ciałach stałych w postaci fali, które możemy usłyszeć.",
 l:"Dźwięk powstaje, gdy coś drga: struna gitary, nasze struny głosowe albo membrana głośnika. Drgania popychają cząsteczki powietrza, te popychają sąsiednie i fala dociera do naszych uszu. Dźwięk potrzebuje ośrodka, dlatego w niemal pustej przestrzeni kosmicznej panuje cisza. Szybsze drgania dają wyższy ton, a większe – głośniejszy dźwięk. Głośność często podaje się w decybelach.",
 x:"Policz sekundy między błyskawicą a grzmotem: około trzech sekund oznacza, że burza jest kilometr od nas.",
 f:"W 1947 roku amerykański pilot Chuck Yeager jako pierwszy pilot w potwierdzonym locie przekroczył prędkość dźwięku, w samolocie rakietowym Bell X-1.",
 js:"To, co słyszymy, gdy coś drga i porusza powietrze.",
 jl:"Kiedy szarpniesz gumkę recepturkę, drga ona bardzo szybko. Drgania poruszają powietrze, a ruch powietrza dociera do twoich uszu. To jest dźwięk. Szybkie drgania dają wysokie, piskliwe dźwięki, a wolne – niskie i dudniące.",
 jx:"Położyłam rękę na gardle i czułam dźwięk, kiedy nuciłam."},
{id:"phy_refraction",cat:"phy",t:"Załamanie światła (refrakcja)",
 s:"Zmiana kierunku światła lub innej fali przy przejściu z jednego ośrodka do drugiego.",
 l:"Światło porusza się w różnych ośrodkach z różną szybkością, na przykład wolniej w wodzie czy szkle niż w powietrzu. Gdy pod kątem przechodzi przez granicę między nimi, zmienia kierunek. Dlatego słomka w szklance wody wygląda na złamaną przy powierzchni, a basen wydaje się płytszy, niż jest naprawdę. Soczewki w okularach, aparatach i mikroskopach wykorzystują załamanie do skupiania światła. Tęcza powstaje, gdy światło słoneczne załamuje się i odbija w kroplach deszczu.",
 x:"Przez załamanie światła moneta na dnie basenu wydawała się bliżej, niż była.",
 f:"Izaak Newton za pomocą szklanego pryzmatu pokazał, że białe światło jest mieszaniną barw, z których każda załamuje się trochę inaczej.",
 js:"Światło, które zmienia kierunek, gdy wpada do wody albo szkła.",
 jl:"Włóż ołówek do szklanki z wodą i popatrz z boku. Ołówek wygląda, jakby się złamał przy powierzchni wody. Naprawdę jest cały, tylko światło zmienia kierunek, gdy przechodzi z wody do powietrza. Okulary pomagają widzieć, bo sprytnie zaginają światło.",
 jx:"Łyżeczka w szklance wody wyglądała, jakby była przełamana na pół."},
{id:"phy_spectrum",cat:"phy",t:"Widmo fal elektromagnetycznych",
 s:"Cały zakres fal elektromagnetycznych, od fal radiowych po promieniowanie gamma, którego niewielką częścią jest światło widzialne.",
 l:"Światło widzialne to tylko jeden rodzaj fal elektromagnetycznych. Fale dłuższe od niego to podczerwień, mikrofale i fale radiowe, a krótsze to ultrafiolet, promieniowanie rentgenowskie i gamma. Wszystkie w próżni poruszają się z prędkością światła. Różne części widma mają różne zastosowania: fale radiowe w radiu i telewizji, mikrofale w kuchenkach i telefonach komórkowych, podczerwień w pilotach, a promienie rentgenowskie do zaglądania do wnętrza ciała.",
 x:"Astronomowie badają niebo w całym widmie fal elektromagnetycznych, nie tylko w świetle widzialnym.",
 f:"W 1800 roku astronom William Herschel umieścił termometry za czerwonym końcem widma z pryzmatu i zauważył, że się nagrzewają – tak odkryto podczerwień.",
 js:"Wielka rodzina fal świetlnych, widzialnych i niewidzialnych.",
 jl:"Światło, które widzimy, to tylko jeden członek wielkiej rodziny fal. Inni członkowie są dla nas niewidzialni: fale radiowe, które przenoszą muzykę, podczerwień z pilota do telewizora albo ultrafiolet ze Słońca, który może poparzyć skórę.",
 jx:"Nasz pilot do telewizora wysyła niewidzialną podczerwień."},
{id:"phy_temperature",cat:"phy",t:"Temperatura i ciepło",
 s:"Temperatura mówi, jak ciepłe lub zimne jest ciało, a ciepło to energia przepływająca od ciała cieplejszego do chłodniejszego.",
 l:"Cząsteczki tworzące każdą substancję nieustannie się poruszają, a temperatura mówi, jak szybko średnio się ruszają. Ciepło to energia przekazywana między ciałami z powodu różnicy temperatur i zawsze płynie od cieplejszego do chłodniejszego. Wanna ciepłej wody zawiera znacznie więcej energii cieplnej niż kubek wrzącej herbaty, choć herbata ma wyższą temperaturę. Temperaturę podaje się w stopniach Celsjusza albo w kelwinach.",
 x:"Zupa szybko stygła, bo ciepło przepływało do zimnej miski.",
 f:"Anders Celsjusz, tworząc swoją skalę w 1742 roku, przyjął zero jako temperaturę wrzenia wody, a sto jako temperaturę zamarzania; wkrótce potem skalę odwrócono.",
 js:"Jak ciepłe albo zimne coś jest i ciepło, które płynie od gorącego do zimnego.",
 jl:"Termometr pokazuje temperaturę, więc wiesz, czy jest mroźny zimowy dzień, czy upalne lato. Ciepło zawsze przechodzi od cieplejszych rzeczy do zimniejszych. Dlatego gorące kakao stygnie, a kostka lodu topi się w dłoni.",
 jx:"Pielęgniarka zmierzyła mi temperaturę termometrem."},
{id:"phy_states_matter",cat:"phy",t:"Stany skupienia materii",
 s:"Różne postacie, w jakich może występować materia, głównie stała, ciekła i gazowa.",
 l:"W ciele stałym cząsteczki są ciasno upakowane i drgają w miejscu, dlatego zachowuje ono kształt. W cieczy są nadal blisko siebie, ale mogą się przesuwać, więc ciecz płynie i przyjmuje kształt naczynia. W gazie cząsteczki są daleko od siebie i swobodnie się poruszają, wypełniając całą dostępną przestrzeń. Ogrzewanie lub chłodzenie zmienia stan skupienia: zachodzi topnienie, krzepnięcie, parowanie, skraplanie. Czwartym stanem jest plazma, bardzo gorący gaz złożony z naładowanych cząstek.",
 x:"Najprostszym przykładem stanów skupienia jest woda: lód, woda w kranie i para.",
 f:"Plazma to najczęstszy stan widzialnej materii we Wszechświecie, bo składają się z niej gwiazdy, także Słońce.",
 js:"Różne postacie, w jakich mogą być rzeczy: stała, ciekła albo gazowa.",
 jl:"Woda może być twardym lodem, płynną cieczą albo niewidzialną parą. To są stany skupienia. Ciało stałe trzyma swój kształt, ciecz płynie i wypełnia kubek, a gaz rozchodzi się wszędzie. Ogrzanie albo ochłodzenie może zmienić jeden stan w drugi.",
 jx:"W słońcu mój lód na patyku zmienił się z ciała stałego w ciecz."},
{id:"phy_density",cat:"phy",t:"Gęstość",
 s:"Wielkość mówiąca, ile masy mieści się w określonej objętości substancji.",
 l:"Gęstość to masa podzielona przez objętość. Kilogram pierza i kilogram żelaza mają tę samą masę, ale żelazo zajmuje znacznie mniej miejsca, więc ma dużo większą gęstość. Ciała o mniejszej gęstości niż woda pływają, a o większej toną – dlatego olej tworzy warstwę na powierzchni wody. Stalowe statki unoszą się na wodzie, bo ich wydrążony, wypełniony powietrzem kadłub sprawia, że średnia gęstość całego statku jest mniejsza niż gęstość wody.",
 x:"Jajko zatonęło w wodzie z kranu, ale pływało w bardzo słonej, która ma większą gęstość.",
 f:"Lód ma mniejszą gęstość niż ciekła woda, co jest niezwykłe; dzięki temu jeziora zamarzają od góry, a ryby mogą przetrwać zimę pod lodem.",
 js:"Jak ciasno coś jest upchnięte w danym miejscu.",
 jl:"Kulka waty i kamyk mogą być tej samej wielkości, ale kamyk jest dużo cięższy. To dlatego, że ma większą gęstość: w tym samym miejscu mieści się więcej materii. Rzeczy o mniejszej gęstości niż woda pływają, jak gumowa kaczka, a te o większej toną, jak kamień.",
 jx:"Nasz test gęstości pokazał, że jabłko pływa, a ziemniak tonie."},
{id:"phy_pressure",cat:"phy",t:"Ciśnienie",
 s:"Siła naciskająca na powierzchnię podzielona przez pole tej powierzchni.",
 l:"Ta sama siła może wywierać bardzo różne ciśnienie. Ostry nóż dobrze tnie, bo jego nacisk skupia się na bardzo wąskim ostrzu, a rakiety śnieżne rozkładają ciężar człowieka na dużą powierzchnię, więc się nie zapada. Ciecze i gazy też wywierają ciśnienie: powietrze naciska na wszystko wokół nas, a ciśnienie wody rośnie wraz z głębokością. Ciśnienie mierzy się w paskalach, nazwanych od francuskiego uczonego Blaise’a Pascala; w prognozach pogody podaje się hektopaskale.",
 x:"W oponach roweru było za niskie ciśnienie, więc pedałowało się ciężko.",
 f:"W 1643 roku włoski uczony Evangelista Torricelli zbudował pierwszy barometr rtęciowy, czyli przyrząd do pomiaru ciśnienia powietrza.",
 js:"Jak mocno coś naciska na powierzchnię.",
 jl:"Jeśli przyciśniesz całą dłoń do miękkiego piasku, zostawisz płytki ślad. Jeśli przyciśniesz tak samo mocno jednym palcem, palec zapadnie się głębiej. To dlatego, że nacisk skupia się na mniejszym miejscu, więc ciśnienie jest większe.",
 jx:"Tata pompował piłkę, aż ciśnienie było w sam raz."},
{id:"phy_radioactivity",cat:"phy",t:"Promieniotwórczość (radioaktywność)",
 s:"Zjawisko samorzutnego rozpadu niestabilnych jąder atomowych, połączonego z wysyłaniem promieniowania.",
 l:"Niektóre atomy mają nietrwałe jądra. Z czasem przemieniają się w inne atomy i wysyłają energię w postaci promieniowania. Każda substancja promieniotwórcza ma swój czas połowicznego rozpadu, czyli czas, po którym rozpada się połowa jej atomów; może on trwać ułamek sekundy albo miliardy lat. Promieniowanie może uszkadzać żywe komórki, dlatego obchodzi się z nim ostrożnie, ale jest też bardzo przydatne: w medycynie, w czujnikach dymu, w datowaniu zabytków i w elektrowniach jądrowych.",
 x:"Archeolodzy wykorzystali promieniotwórczy węgiel, żeby oszacować wiek drewnianej belki.",
 f:"Promieniotwórczość odkrył Henri Becquerel w 1896 roku, a samo słowo radioaktywność wprowadzili Maria Skłodowska-Curie i Piotr Curie.",
 js:"Gdy niektóre atomy powoli się rozpadają i wysyłają niewidzialne promienie.",
 jl:"Niektóre rodzaje atomów są w środku trochę chwiejne. Z czasem się rozpadają i wysyłają niewidzialną energię zwaną promieniowaniem. Za dużo promieniowania szkodzi, więc naukowcy używają specjalnych osłon. Lekarze ostrożnie korzystają z niego, żeby zajrzeć do wnętrza ciała i leczyć choroby.",
 jx:"Przeczytałem, że Maria Skłodowska-Curie badała promieniotwórczość."},
{id:"phy_relativity",cat:"phy",t:"Teoria względności",
 s:"Teorie Alberta Einsteina opisujące, jak powiązane są ze sobą przestrzeń, czas, ruch i grawitacja.",
 l:"Szczególną teorię względności Einstein ogłosił w 1905 roku. Mówi ona, że prędkość światła jest taka sama dla każdego obserwatora i że dla ciał poruszających się bardzo szybko czas płynie wolniej niż dla obserwatora w spoczynku. Z tej teorii wynika też słynny wzór E równa się m c kwadrat, pokazujący związek masy z energią. Ogólna teoria względności z 1915 roku wyjaśnia grawitację jako zakrzywienie czasoprzestrzeni przez masę. Obie zostały potwierdzone w wielu doświadczeniach.",
 x:"Nawigacja satelitarna myliłaby się o kilometry dziennie, gdyby inżynierowie pominęli teorię względności.",
 f:"Zegary na satelitach GPS chodzą odrobinę inaczej niż zegary na Ziemi, a system musi poprawiać ten efekt przewidziany przez teorię względności.",
 js:"Wielkie pomysły Einsteina o przestrzeni, czasie i bardzo szybkich podróżach.",
 jl:"Albert Einstein odkrył, że czas i przestrzeń potrafią się rozciągać i ściskać. Dla czegoś, co pędzi niemal tak szybko jak światło, czas płynie odrobinę wolniej. Na co dzień tego nie zauważamy, ale naukowcy zmierzyli to bardzo dokładnymi zegarami.",
 jx:"W bibliotece znalazłem obrazkową książkę o Einsteinie i teorii względności."},
{id:"phy_pl_polon",cat:"phy",only:1,t:"Polon",
 s:"Promieniotwórczy pierwiastek chemiczny odkryty w 1898 roku przez Marię Skłodowską-Curie i Piotra Curie i nazwany na cześć Polski.",
 l:"Badając rudę uranu, małżonkowie Curie zauważyli, że promieniuje ona silniej, niż wynikałoby z zawartego w niej uranu. Doszli do wniosku, że kryje się w niej nieznany pierwiastek, i w lipcu 1898 roku ogłosili jego odkrycie. Maria nadała mu nazwę od łacińskiego słowa Polonia, czyli Polska. W układzie okresowym polon ma liczbę atomową osiemdziesiąt cztery i symbol Po. Jest bardzo rzadki i silnie promieniotwórczy, dlatego bada się go tylko w specjalnych laboratoriach.",
 x:"Na lekcji chemii dowiedzieliśmy się, że polon to jedyny pierwiastek nazwany od Polski.",
 f:"Gdy odkryto polon, Polski nie było na mapie, bo jej ziemie były podzielone między zaborców; nazwa miała przypomnieć światu o polskim narodzie.",
 js:"Pierwiastek, który Maria Skłodowska-Curie nazwała na cześć Polski.",
 jl:"Maria Skłodowska-Curie razem z mężem Piotrem odkryła nowy pierwiastek, czyli nowy rodzaj atomów. Nazwała go polon, od łacińskiej nazwy Polski. Chciała, żeby cały świat pamiętał o jej ojczyźnie, której wtedy nie było na mapie.",
 jx:"Pokazałam koleżance w układzie okresowym polon, nazwany od Polski."},
{id:"phy_pl_reaktor_maria",cat:"phy",only:1,t:"Reaktor Maria",
 s:"Jedyny działający w Polsce jądrowy reaktor badawczy, znajdujący się w Narodowym Centrum Badań Jądrowych w Otwocku-Świerku.",
 l:"Reaktor Maria nie wytwarza prądu dla sieci energetycznej; służy nauce i medycynie. Strumień neutronów z reaktora wykorzystuje się do badań materiałów oraz do wytwarzania izotopów promieniotwórczych, z których powstają preparaty stosowane w szpitalach do diagnozowania i leczenia chorób. Reaktor uruchomiono w 1974 roku i od tego czasu był wielokrotnie modernizowany. Nazwano go na cześć Marii Skłodowskiej-Curie. Wcześniej w Świerku działał reaktor Ewa, pierwszy w Polsce.",
 x:"Izotopy wytwarzane dzięki reaktorowi Maria wykorzystuje się w szpitalach.",
 f:"Pierwszy polski reaktor jądrowy, Ewa, uruchomiono w Świerku w 1958 roku.",
 js:"Polski reaktor jądrowy, który pomaga lekarzom i naukowcom.",
 jl:"Pod Warszawą, w Świerku, działa reaktor jądrowy o imieniu Maria. Nie robi prądu do gniazdek. Pomaga naukowcom w badaniach i wytwarza specjalne substancje, dzięki którym lekarze mogą zobaczyć, co dzieje się w ciele chorego, i go leczyć.",
 jx:"Reaktor Maria dostał imię na cześć Marii Skłodowskiej-Curie."},
{id:"phy_pl_wroblewski_olszewski",cat:"phy",only:1,t:"Wróblewski i Olszewski",
 s:"Krakowscy uczeni, którzy w 1883 roku jako pierwsi skroplili tlen i azot z powietrza w trwałej, dającej się badać ilości.",
 l:"Zygmunt Wróblewski i Karol Olszewski pracowali na Uniwersytecie Jagiellońskim. Łącząc wysokie ciśnienie z bardzo silnym chłodzeniem, w kwietniu 1883 roku otrzymali ciekły tlen, a kilka dni później ciekły azot. Wcześniej inni badacze uzyskali jedynie przelotną mgiełkę kropelek. Osiągnięcie to otworzyło drogę do badań bardzo niskich temperatur, czyli kriogeniki, z której korzystają dziś na przykład szpitale i laboratoria.",
 x:"Na wycieczce do Krakowa przewodnik opowiadał nam o Wróblewskim i Olszewskim.",
 f:"Ciekły tlen ma bladoniebieską barwę i jest przyciągany przez silny magnes.",
 js:"Dwóch uczonych z Krakowa, którzy zamienili powietrze w ciecz.",
 jl:"Dawno temu w Krakowie dwóch naukowców, Zygmunt Wróblewski i Karol Olszewski, bardzo mocno ochłodziło i ścisnęło gazy z powietrza. Udało im się zamienić tlen i azot w płyny. Ciekły tlen ma śliczny, bladoniebieski kolor.",
 jx:"Pan od fizyki opowiadał, jak Wróblewski i Olszewski skroplili tlen w Krakowie."},
{id:"phy_pl_smoluchowski",cat:"phy",only:1,t:"Marian Smoluchowski",
 s:"Polski fizyk, który w 1906 roku wyjaśnił ruchy Browna niezależnie od Alberta Einsteina.",
 l:"Marian Smoluchowski żył w latach 1872–1917 i był profesorem we Lwowie, a potem w Krakowie. Zajmował się zjawiskiem zauważonym przez botanika Roberta Browna: drobiny zawieszone w cieczy wykonują nieustanne, chaotyczne ruchy. Smoluchowski pokazał, że wywołują je uderzenia niewidzialnych cząsteczek cieczy, i opisał to matematycznie. Jego prace pomogły przekonać naukowców, że atomy i cząsteczki naprawdę istnieją. Badał też, dlaczego niebo jest niebieskie i jak rozprasza się światło.",
 x:"Na wykładzie o cząsteczkach profesor wspomniał o Marianie Smoluchowskim.",
 f:"W 1917 roku wybrano go na rektora Uniwersytetu Jagiellońskiego, ale zmarł, zanim objął urząd.",
 js:"Polski fizyk, który wyjaśnił, dlaczego pyłki w wodzie same się ruszają.",
 jl:"Gdy patrzymy przez mikroskop na malutkie pyłki w wodzie, widać, że ciągle drgają i skaczą. Marian Smoluchowski wyjaśnił, że popychają je niewidzialne cząsteczki wody, które bez przerwy się poruszają. To była ważna wskazówka, że atomy istnieją naprawdę.",
 jx:"Pod mikroskopem zobaczyliśmy ruchy Browna, które wyjaśnił Marian Smoluchowski."},
/* ---------- ASTRONOMIA (+6) ---------- */
{id:"ast_star",cat:"ast",t:"Gwiazda",
 s:"Ogromna kula gorącego gazu, która wytwarza światło i ciepło dzięki reakcjom termojądrowym w swoim wnętrzu.",
 l:"W środku gwiazdy jądra wodoru są ściskane tak mocno, że łączą się w hel, a przy tym uwalnia się olbrzymia ilość energii. Energia ta powoli wydostaje się na zewnątrz i wypromieniowuje w przestrzeń jako światło. Gwiazdy różnią się wielkością, jasnością i barwą: najgorętsze są niebiesko-białe, a chłodniejsze pomarańczowe lub czerwone. Rodzą się w obłokach gazu i pyłu i mogą świecić przez miliony lub miliardy lat. Słońce jest zwyczajną, średniej wielkości gwiazdą.",
 x:"Z dala od miejskich świateł widzieliśmy tysiące gwiazd.",
 f:"Najbliższą gwiazdą po Słońcu jest Proxima Centauri, oddalona o około cztery i dwie dziesiąte roku świetlnego.",
 js:"Olbrzymia, świecąca kula gorącego gazu daleko w kosmosie.",
 jl:"Gwiazdy wyglądają jak małe migoczące kropki, ale to ogromne kule rozżarzonego gazu, często dużo większe od Słońca. Wydają się małe tylko dlatego, że są bardzo daleko. Słońce też jest gwiazdą, po prostu znajduje się bardzo blisko nas.",
 jx:"Pomyślałam życzenie, patrząc na pierwszą gwiazdę na wieczornym niebie."},
{id:"ast_sun",cat:"ast",t:"Słońce",
 s:"Gwiazda w centrum Układu Słonecznego, która daje Ziemi światło i ciepło.",
 l:"Słońce to kula gorącej plazmy, złożona głównie z wodoru i helu, około stu dziewięciu razy szersza od Ziemi. Powstało około czterech i pół miliarda lat temu i jest mniej więcej w połowie swojego życia. Jego energia napędza pogodę i klimat na Ziemi i pozwala roślinom rosnąć. Światło słoneczne leci do nas nieco ponad osiem minut. Nigdy nie patrz prosto w Słońce, nawet przez okulary przeciwsłoneczne, bo może to trwale uszkodzić wzrok.",
 x:"Słońce wzeszło nad wzgórzami tuż po siódmej.",
 f:"W Słońcu skupia się około dziewięćdziesięciu dziewięciu i ośmiu dziesiątych procent całej masy Układu Słonecznego.",
 js:"Nasza gwiazda, która daje nam dzień i ciepło.",
 jl:"Słońce jest gwiazdą, i to najbliższą nam. Jest tak wielkie, że zmieściłoby się w nim ponad milion Ziem. Daje nam światło i ciepło, a rośliny potrzebują go do wzrostu. Nigdy nie patrz prosto w Słońce, bo może to zranić oczy.",
 jx:"Przed zabawą na słońcu posmarowaliśmy się kremem z filtrem."},
{id:"ast_tides",cat:"ast",t:"Pływy (przypływy i odpływy)",
 s:"Regularne podnoszenie się i opadanie poziomu morza, wywołane głównie przyciąganiem Księżyca.",
 l:"Księżyc przyciąga całą Ziemię, ale nieco mocniej stronę zwróconą do niego, a nieco słabiej stronę przeciwną. Rozciąga to oceany w dwa wybrzuszenia, więc na większości wybrzeży mniej więcej w ciągu doby są dwa przypływy i dwa odpływy. Słońce dokłada swoje słabsze przyciąganie: przy nowiu i pełni pływy są większe, a przy kwadrach mniejsze. W zamkniętych morzach pływy są bardzo małe – na Bałtyku to zaledwie kilka centymetrów, więc na polskich plażach prawie ich nie widać.",
 x:"Nad Atlantykiem czekaliśmy na odpływ, żeby obejrzeć skalne baseny pełne krabów.",
 f:"W Zatoce Fundy w Kanadzie występują jedne z największych pływów na świecie – poziom wody zmienia się tam nawet o około szesnaście metrów.",
 js:"Morze, które codziennie podchodzi wyżej i znów się cofa.",
 jl:"Nad oceanem woda powoli wpełza na plażę, a potem znów się cofa. To przypływ i odpływ. Dzieje się tak, bo Księżyc przyciąga wodę w oceanach. Nad naszym Bałtykiem prawie tego nie widać, bo to małe, zamknięte morze.",
 jx:"We Francji przypływ zabrał nasz zamek z piasku."},
{id:"ast_satellite",cat:"ast",t:"Satelita",
 s:"Ciało krążące wokół planety lub innego większego ciała – naturalne, jak Księżyc, albo zbudowane przez ludzi.",
 l:"Księżyc jest naturalnym satelitą Ziemi, a inne planety mają wiele własnych księżyców. Sztuczne satelity to urządzenia wynoszone na orbitę przez rakiety. Przekazują sygnał telewizyjny i telefoniczny, pomagają w nawigacji, fotografują chmury, obserwują lasy i lodowce oraz badają Wszechświat. Satelita nie spada, bo porusza się w bok tak szybko, że gdy opada ku Ziemi, jej powierzchnia zakrzywia się pod nim. Dziś wokół naszej planety krążą tysiące działających satelitów.",
 x:"W prognozie pogody pokazano zdjęcia chmur zrobione przez satelitę.",
 f:"Pierwszego sztucznego satelitę, Sputnika 1, wystrzelił Związek Radziecki 4 października 1957 roku; wysyłał on proste piszczące sygnały radiowe.",
 js:"Coś, co krąży dookoła planety.",
 jl:"Księżyc krąży wokół Ziemi, więc jest satelitą. Ludzie też budują satelity i wysyłają je w kosmos rakietami. Dzięki nim oglądamy telewizję, znajdujemy drogę na mapie w telefonie i wiemy, jaka będzie jutro pogoda.",
 jx:"Tata powiedział, że ta przesuwająca się kropka na niebie to satelita."},
{id:"ast_solar_system",cat:"ast",t:"Układ Słoneczny",
 s:"Słońce i wszystko, co wokół niego krąży: planety, księżyce, planety karłowate, planetoidy i komety.",
 l:"Układ Słoneczny powstał około czterech i pół miliarda lat temu z wirującego obłoku gazu i pyłu. W środku jest Słońce, które swoją grawitacją utrzymuje całość. Wokół niego krąży osiem planet z księżycami, planety karłowate, takie jak Pluton, pas planetoid między Marsem a Jowiszem oraz lodowe ciała daleko za Neptunem. Trudno wskazać, gdzie dokładnie się kończy, bo grawitacja Słońca sięga bardzo daleko. To jeden z wielu układów planetarnych w Drodze Mlecznej.",
 x:"Zbudowaliśmy model Układu Słonecznego z kulek różnej wielkości.",
 f:"Sonda Voyager 1, wystrzelona w 1977 roku, jako pierwszy obiekt zbudowany przez ludzi opuściła w 2012 roku obszar wiatru słonecznego i weszła w przestrzeń międzygwiazdową.",
 js:"Słońce i wszystkie planety i inne ciała, które wokół niego krążą.",
 jl:"Układ Słoneczny jest jak wielka rodzina ze Słońcem w środku. Krąży wokół niego osiem planet, w tym Ziemia. Wiele planet ma księżyce, są też skaliste planetoidy i lodowe komety. Ziemia to jedyne miejsce, o którym wiemy, że jest na nim życie.",
 jx:"Na suficie w moim pokoju są świecące w ciemności naklejki z Układem Słonecznym."},
{id:"ast_pl_wolszczan",cat:"ast",only:1,t:"Aleksander Wolszczan",
 s:"Polski astronom, który w 1992 roku ogłosił odkrycie pierwszych potwierdzonych planet poza Układem Słonecznym.",
 l:"Aleksander Wolszczan urodził się w 1946 roku w Szczecinku i jest związany z Uniwersytetem Mikołaja Kopernika w Toruniu oraz z uczelnią w Stanach Zjednoczonych. Badając za pomocą radioteleskopu w Arecibo pulsar oznaczony PSR B1257+12, zauważył drobne zmiany w rytmie jego sygnałów. Razem z Dale’em Frailem wykazał, że wywołują je krążące wokół pulsara planety. Było to pierwsze potwierdzone odkrycie planet pozasłonecznych, choć krążą one wokół martwej gwiazdy, a nie zwykłej, takiej jak Słońce.",
 x:"O Aleksandrze Wolszczanie usłyszałam na festiwalu nauki w Toruniu.",
 f:"W 2015 roku w ogólnoświatowym konkursie nadano tym obiektom nazwy: pulsar nazwano Lich, a jego planety Draugr, Poltergeist i Phobetor.",
 js:"Polski astronom, który jako pierwszy znalazł planety przy innej gwieździe.",
 jl:"Aleksander Wolszczan to polski naukowiec, który słuchał sygnałów z kosmosu wielkim radioteleskopem. Zauważył, że sygnały z pewnej gwiazdy co jakiś czas leciutko się zmieniają. Okazało się, że krążą wokół niej planety. To były pierwsze potwierdzone planety poza naszym Układem Słonecznym.",
 jx:"Pani powiedziała, że pierwsze planety przy innej gwieździe odkrył Polak, Aleksander Wolszczan."},
/* ---------- MEDYCYNA (+6) ---------- */
{id:"m_immune_system",cat:"med",t:"Układ odpornościowy",
 s:"Sieć komórek, tkanek i narządów, która broni organizm przed drobnoustrojami i innymi zagrożeniami.",
 l:"Do układu odpornościowego należą białe krwinki, przeciwciała, węzły chłonne, śledziona, szpik kostny i grasica. Jego pierwsza linia obrony szybko reaguje na wszystko, co obce, a druga, wolniejsza, uczy się rozpoznawać konkretne drobnoustroje i je zapamiętuje. Ta pamięć sprawia, że wiele chorób przechodzimy łagodniej albo nie chorujemy ponownie, i właśnie ją trenują szczepionki. Czasem układ odpornościowy reaguje zbyt mocno, jak w alergii, albo atakuje własne tkanki, jak w chorobach autoimmunologicznych.",
 x:"Po przeziębieniu jej układ odpornościowy zapamiętał tego wirusa.",
 f:"Limfocyty T, jeden z najważniejszych rodzajów białych krwinek, zawdzięczają nazwę grasicy, po łacinie thymus – małemu narządowi w klatce piersiowej, w którym dojrzewają.",
 js:"Własna drużyna obrońców twojego ciała przed zarazkami.",
 jl:"W twoim ciele działa sprytna drużyna obrońców, czyli układ odpornościowy. Kiedy do środka dostaną się zarazki, specjalne komórki je odnajdują i zwalczają. Potem drużyna pamięta te zarazki, więc następnym razem pokona je dużo szybciej. Pomaga jej sen i zdrowe jedzenie.",
 jx:"Miałem katar, ale mój układ odpornościowy poradził sobie z nim w kilka dni."},
{id:"m_stethoscope",cat:"med",t:"Stetoskop (słuchawki lekarskie)",
 s:"Przyrząd lekarski do osłuchiwania dźwięków wewnątrz ciała, na przykład pracy serca i płuc.",
 l:"Stetoskop ma płaską głowicę, która zbiera dźwięki, przewody, które je prowadzą, i oliwki wkładane do uszu. Osłuchując pacjenta, lekarz lub pielęgniarka słyszy rytm serca, przepływ powietrza w płucach i pracę jelit. Nietypowe dźwięki, na przykład szmer nad sercem albo trzeszczenia w płucach, mogą być wskazówką, że potrzebne są dalsze badania. Stetoskopu używa się też razem z mankietem do ręcznego pomiaru ciśnienia krwi.",
 x:"Lekarka ogrzała stetoskop w dłoni, zanim osłuchała mi plecy.",
 f:"Stetoskop wynalazł w 1816 roku francuski lekarz René Laennec, zaczynając od zwiniętej w rulon kartki papieru; nazwa pochodzi od greckich słów oznaczających pierś i oglądanie.",
 js:"Narzędzie, którym lekarz słucha serca i oddechu.",
 jl:"Stetoskop ma dwie słuchawki do uszu, długą rurkę i okrągłą końcówkę. Lekarz przykłada końcówkę do twojej piersi albo pleców i słucha. Słyszy, jak serce robi puk-puk, a powietrze szumi w płucach. To wcale nie boli, choć bywa trochę zimne.",
 jx:"Pani doktor pozwoliła mi posłuchać przez stetoskop mojego własnego serca."},
{id:"m_hormone",cat:"med",t:"Hormon",
 s:"Chemiczny przekaźnik wytwarzany przez gruczoł i przenoszony z krwią, który steruje pracą innych części ciała.",
 l:"Hormony regulują wzrost, sen, głód, nastrój, reakcję na stres, poziom cukru we krwi i dojrzewanie. Wytwarzają je między innymi tarczyca, nadnercza, trzustka i przysadka mózgowa u podstawy mózgu. Ponieważ krążą z krwią, mogą działać na wiele narządów naraz, ale każdy wpływa tylko na komórki mające odpowiednie receptory. Zbyt dużo lub zbyt mało hormonu może wywołać chorobę, a wiele takich zaburzeń da się skutecznie leczyć.",
 x:"Insulina to hormon, który pomaga organizmowi wykorzystać cukier z pożywienia.",
 f:"Słowo hormon wprowadził w 1905 roku brytyjski fizjolog Ernest Starling, od greckiego słowa oznaczającego pobudzać, wprawiać w ruch.",
 js:"Malutka chemiczna wiadomość, która podróżuje z krwią.",
 jl:"Twoje ciało wysyła wiadomości na dwa sposoby: szybkie przez nerwy i wolniejsze przez krew. Te wolniejsze posłańce to hormony. Pomagają ci rosnąć, mówią, kiedy jesteś głodny albo śpiący, i szykują cię do ucieczki, gdy się przestraszysz.",
 jx:"Hormon wzrostu działa głównie w nocy, więc dobry sen pomaga rosnąć."},
{id:"m_ultrasound",cat:"med",t:"USG (badanie ultrasonograficzne)",
 s:"Badanie, w którym obraz wnętrza ciała tworzy się za pomocą fal dźwiękowych o bardzo wysokiej częstotliwości.",
 l:"Głowica przykładana do skóry wysyła dźwięki za wysokie, by ludzie mogli je usłyszeć, i odbiera ich echo odbite od narządów i tkanek. Komputer zamienia echo na ruchomy obraz na ekranie. USG wykonuje się bardzo często w ciąży, żeby sprawdzić rozwój dziecka, a także do badania serca, wątroby, nerek, tarczycy, naczyń krwionośnych czy mięśni. Nie wykorzystuje promieniowania rentgenowskiego i zwykle jest bezbolesne; na skórę nakłada się tylko chłodny żel.",
 x:"Na USG zobaczyliśmy, jak bije serce dziecka.",
 f:"Jednym z pionierów zastosowania ultrasonografii w położnictwie był szkocki lekarz Ian Donald z Glasgow, który opublikował przełomową pracę w 1958 roku.",
 js:"Badanie, które dźwiękiem robi obrazek wnętrza ciała.",
 jl:"Przy badaniu USG lekarz nakłada ci na skórę trochę zimnego, śliskiego żelu i przesuwa po nim małą głowicę. Głowica wysyła dźwięki, których nie słychać. Ich echo tworzy obrazek na ekranie. To trochę jak u nietoperzy, które w ciemności orientują się dzięki echu.",
 jx:"Mama pokazała mi zdjęcie z USG mojej siostrzyczki, zanim się urodziła."},
{id:"m_antiseptic",cat:"med",t:"Środek antyseptyczny i dezynfekcyjny",
 s:"Środek antyseptyczny niszczy drobnoustroje na skórze i w ranach, a dezynfekcyjny robi to samo na przedmiotach i powierzchniach.",
 l:"Oba rodzaje zmniejszają liczbę drobnoustrojów, które mogłyby wywołać zakażenie, ale służą do czego innego. Środki antyseptyczne są na tyle łagodne, że można je stosować na żywe tkanki – do przemywania ran czy skóry przed zabiegiem. Środki dezynfekcyjne są mocniejsze i przeznaczone do podłóg, blatów i sprzętu medycznego; nie wolno ich nakładać na skórę. Żaden z nich nie zastępuje zwykłego mycia rąk wodą z mydłem, które usuwa większość zarazków. Zawsze trzeba przestrzegać instrukcji na etykiecie.",
 x:"Pielęgniarka przemyła otarcie środkiem antyseptycznym.",
 f:"W 1867 roku brytyjski chirurg Joseph Lister opisał, jak przemywanie ran kwasem karbolowym ogromnie zmniejszyło liczbę zgonów po operacjach.",
 js:"Płyny zabijające zarazki: jeden do ran, drugi do powierzchni.",
 jl:"Kiedy obetrzesz kolano, dorosły może je przemyć środkiem antyseptycznym, który jest łagodny dla skóry i zabija zarazki. Do mycia stołów i łazienki używa się środków dezynfekcyjnych. Są dużo mocniejsze i nie wolno ich dawać na skórę.",
 jx:"Pani pielęgniarka przemyła mi kolano i trochę zaszczypało."},
{id:"m_pl_ikp",cat:"med",only:1,c:"Polska",t:"Internetowe Konto Pacjenta (IKP)",
 s:"Bezpłatna usługa internetowa, w której pacjent w Polsce znajdzie swoje e-recepty, e-skierowania i inne dane o leczeniu.",
 l:"Do Internetowego Konta Pacjenta loguje się przez stronę pacjent.gov.pl lub aplikację mojeIKP, na przykład profilem zaufanym, aplikacją mObywatel albo przez bankowość elektroniczną. Na koncie widać wystawione e-recepty i e-skierowania, historię wizyt finansowanych przez NFZ, zwolnienia lekarskie i informacje o szczepieniach. Można tam też zgłosić się na niektóre szczepienia i badania profilaktyczne. Rodzic ma dostęp do konta dziecka, dopóki nie skończy ono osiemnastu lat.",
 x:"Sprawdziłam w IKP, czy lekarz wystawił już e-receptę.",
 f:"W IKP można upoważnić bliską osobę do wglądu w swoją dokumentację medyczną albo do uzyskiwania informacji o stanie zdrowia.",
 js:"Konto w internecie, na którym rodzice widzą recepty i szczepienia dziecka.",
 jl:"Internetowe Konto Pacjenta to takie miejsce w internecie, gdzie dorośli widzą swoje recepty od lekarza i to, jakie mieli szczepienia. Rodzice mogą tam też sprawdzić informacje o zdrowiu swoich dzieci, na przykład kiedy było ostatnie szczepienie.",
 jx:"Mama sprawdziła w IKP, kiedy miałem ostatnie szczepienie."},
/* ---------- PRAWO (+6) ---------- */
{id:"l_employment_contract",cat:"law",c:"Polska",t:"Umowa o pracę",
 s:"Umowa, w której pracownik zobowiązuje się wykonywać pracę pod kierownictwem pracodawcy, a pracodawca – płacić mu wynagrodzenie.",
 l:"Umowę o pracę reguluje Kodeks pracy. Może być zawarta na okres próbny, który zwykle trwa najwyżej trzy miesiące, na czas określony albo na czas nieokreślony. Pracodawca musi potwierdzić warunki umowy na piśmie najpóźniej w dniu rozpoczęcia pracy. Umowa o pracę daje pracownikowi ochronę, jakiej nie zapewniają umowy cywilnoprawne: płatny urlop wypoczynkowy, wynagrodzenie nie niższe od minimalnego, okres wypowiedzenia i ubezpieczenia społeczne.",
 x:"Po okresie próbnym dostała umowę o pracę na czas nieokreślony.",
 f:"Umowy na czas określony z tym samym pracodawcą mogą łącznie trwać najwyżej trzydzieści trzy miesiące i być zawarte najwyżej trzy razy; potem kolejna umowa uznawana jest za zawartą na czas nieokreślony.",
 js:"Umowa, która mówi, jaką pracę ktoś wykonuje i ile za nią dostaje.",
 jl:"Kiedy dorośli zaczynają pracę, ustalają z szefem, co będą robić, w jakich godzinach i ile zarobią. Zapisują to w umowie o pracę. Dzięki niej pracownik ma też prawo do płatnego urlopu, na przykład na wakacje z rodziną.",
 jx:"Ciocia podpisała umowę o pracę w piekarni w pierwszym dniu pracy."},
{id:"l_patent",cat:"law",c:"Polska",t:"Patent",
 s:"Prawo pozwalające wynalazcy zabronić innym wytwarzania, używania i sprzedawania jego wynalazku przez określony czas.",
 l:"Patent można uzyskać na wynalazek, który jest nowy, ma poziom wynalazczy, czyli nie jest oczywisty dla znawcy dziedziny, i nadaje się do przemysłowego stosowania. W Polsce zgłoszenia przyjmuje i rozpatruje Urząd Patentowy Rzeczypospolitej Polskiej. Patent może trwać do dwudziestu lat, jeśli właściciel co roku wnosi opłaty. W zamian wynalazca musi publicznie opisać swój wynalazek, aby inni mogli się z niego uczyć, a po wygaśnięciu patentu swobodnie z niego korzystać.",
 x:"Inżynierka zgłosiła do Urzędu Patentowego swój nowy składany wózek inwalidzki.",
 f:"Słowo patent pochodzi od łacińskiego litterae patentes, czyli listy otwarte – tak nazywano królewskie dokumenty, które każdy mógł przeczytać.",
 js:"Specjalne prawo, które chroni nowy wynalazek.",
 jl:"Jeśli wymyślisz coś zupełnie nowego, na przykład sprytny dzwonek do roweru, możesz poprosić o patent. Wtedy przez kilka lat nikt inny nie może robić ani sprzedawać twojego wynalazku bez twojej zgody. Później z pomysłu mogą korzystać wszyscy.",
 jx:"Dziadek wiele lat temu dostał patent na swój wynalazek."},
{id:"l_legal_aid",cat:"law",c:"Polska",t:"Nieodpłatna pomoc prawna",
 s:"Bezpłatne porady prawne finansowane przez państwo dla osób, których nie stać na odpłatną pomoc prawnika.",
 l:"W każdym powiecie działają punkty nieodpłatnej pomocy prawnej, w których dyżurują adwokaci, radcowie prawni, a czasem doradcy podatkowi lub prawnicy z organizacji pozarządowych. Może z nich skorzystać każda osoba, która złoży oświadczenie, że nie jest w stanie ponieść kosztów odpłatnej pomocy. Na wizytę zwykle trzeba się wcześniej zapisać, a porady bywają udzielane także przez telefon lub internet. W sprawie przed sądem można natomiast poprosić o pełnomocnika z urzędu.",
 x:"W punkcie nieodpłatnej pomocy prawnej radca wyjaśnił jej, jak odpowiedzieć na pismo z sądu.",
 f:"Punkty nieodpłatnej pomocy prawnej działają w Polsce od 2016 roku na podstawie ustawy uchwalonej w 2015 roku.",
 js:"Darmowa pomoc prawnika dla osób, których nie stać na zapłatę.",
 jl:"Prawnik może być drogi. Żeby każdy mógł dostać dobrą radę, w każdym powiecie są miejsca, gdzie prawnik pomaga za darmo osobom, które nie mają dość pieniędzy.",
 jx:"Babcia poszła po darmową poradę prawną do punktu w urzędzie."},
{id:"l_age_criminal_responsibility",cat:"law",c:"Polska",j:false,t:"Wiek odpowiedzialności karnej",
 s:"Wiek, od którego osoba może odpowiadać za przestępstwo przed sądem karnym tak jak dorosły.",
 l:"Według Kodeksu karnego w Polsce odpowiedzialność karna zaczyna się zasadniczo po ukończeniu siedemnastu lat. Wyjątkowo osoba, która skończyła piętnaście lat, może odpowiadać jak dorosły za niektóre najcięższe przestępstwa, jeśli przemawiają za tym okoliczności sprawy. Sprawami młodszych osób, które łamią prawo, zajmują się sądy rodzinne, a celem jest przede wszystkim wychowanie i resocjalizacja, a nie kara. Stosuje się wtedy na przykład nadzór kuratora.",
 x:"Na lekcji wiedzy o społeczeństwie rozmawialiśmy o wieku odpowiedzialności karnej.",
 f:"Od 2022 roku sprawy nieletnich reguluje ustawa o wspieraniu i resocjalizacji nieletnich, która zastąpiła ustawę z 1982 roku."},
{id:"l_parental_responsibility",cat:"law",c:"Polska",t:"Władza rodzicielska",
 s:"Obowiązki i prawa rodziców wobec dziecka, przede wszystkim troska o nie, jego wychowanie i reprezentowanie go.",
 l:"Władzę rodzicielską reguluje Kodeks rodzinny i opiekuńczy. Przysługuje obojgu rodzicom i trwa do pełnoletności dziecka. Rodzice decydują o ważnych sprawach dziecka, takich jak szkoła, leczenie czy miejsce zamieszkania, i powinni robić to wspólnie, kierując się dobrem dziecka. Muszą też, w miarę jego dojrzałości, wysłuchać jego zdania. Gdy dobro dziecka jest zagrożone, sąd rodzinny może władzę rodzicielską ograniczyć, zawiesić albo jej pozbawić.",
 x:"Oboje rodzice mają władzę rodzicielską, więc szkoła informuje ich oboje.",
 f:"Od 2010 roku polskie prawo wyraźnie zakazuje stosowania kar cielesnych wobec dzieci przez osoby wykonujące władzę rodzicielską lub opiekujące się dzieckiem.",
 js:"Obowiązek rodziców, żeby opiekować się dzieckiem i podejmować dla niego dobre decyzje.",
 jl:"Rodzice mają ważne zadanie: dbać, żeby dziecko było bezpieczne, zdrowe i się uczyło. Prawo nazywa to władzą rodzicielską. Rodzice podejmują duże decyzje, na przykład o wyborze szkoły, i powinni przy tym słuchać, co myśli dziecko.",
 jx:"Tata podpisał zgodę na wycieczkę, bo ma władzę rodzicielską."},
{id:"l_pl_umowa_zlecenie",cat:"law",only:1,c:"Polska",t:"Umowa zlecenie",
 s:"Umowa cywilnoprawna, w której zleceniobiorca zobowiązuje się wykonać określone czynności dla zleceniodawcy, bez stosunku pracy.",
 l:"Umowę zlecenie reguluje Kodeks cywilny, a nie Kodeks pracy. Zleceniobiorca zobowiązuje się starannie działać, na przykład prowadzić zajęcia, sprzątać czy obsługiwać klientów, ale nie musi osiągnąć konkretnego rezultatu, co odróżnia ją od umowy o dzieło. Nie daje prawa do płatnego urlopu ani okresu wypowiedzenia jak umowa o pracę, choć obowiązuje minimalna stawka godzinowa. Zwykle odprowadza się od niej składki na ubezpieczenia społeczne, z wyjątkiem na przykład uczniów i studentów do dwudziestu sześciu lat.",
 x:"W wakacje pracował w kawiarni na umowie zlecenie.",
 f:"Od 2017 roku przy umowach zlecenia obowiązuje minimalna stawka godzinowa, ustalana co roku razem z płacą minimalną.",
 js:"Umowa na wykonywanie jakiejś pracy, ale inna niż zwykła umowa o pracę.",
 jl:"Czasem dorośli pracują nie na umowie o pracę, tylko na umowie zlecenie. Na przykład starsza siostra może dorabiać w wakacje w lodziarni. Taka umowa jest prostsza, ale nie daje płatnego urlopu.",
 jx:"Mój brat w wakacje pracował na umowie zlecenie przy zbieraniu truskawek."},
/* ---------- JĘZYK OGÓLNY (+6) ---------- */
{id:"g_anagram",cat:"gen",t:"Anagram",
 s:"Wyraz lub wyrażenie utworzone przez przestawienie wszystkich liter innego wyrazu lub wyrażenia.",
 l:"Tworząc anagram, trzeba wykorzystać każdą literę pierwotnego słowa dokładnie raz, tylko w innej kolejności. Słowo kot można zamienić w tok, mata w tama, a ropa w pora. Anagramy uwielbiają autorzy krzyżówek i miłośnicy gier słownych, a niektórzy pisarze układali z liter swojego nazwiska pseudonimy. Najlepsze anagramy zaskakują, bo nowe słowo jakby komentuje stare.",
 x:"Rozwiązaniem hasła w krzyżówce był anagram słowa ropa, czyli pora.",
 f:"Francuski pisarz François Rabelais wydał część swoich dzieł pod pseudonimem Alcofribas Nasier, który jest anagramem jego prawdziwego imienia i nazwiska.",
 js:"Słowo ułożone z wymieszanych liter innego słowa.",
 jl:"Weź słowo kot i poprzestawiaj litery. Możesz ułożyć tok. To jest anagram. Spróbuj ze słowem mata: przestaw litery, a wyjdzie tama. Anagramy to łamigłówki ukryte w słowach.",
 jx:"Siostra ułożyła anagram ze swojego imienia i powiesiła go na drzwiach."},
{id:"g_portmanteau",cat:"gen",t:"Zbitka wyrazowa (kontaminacja)",
 s:"Wyraz powstały przez połączenie fragmentów dwóch innych wyrazów, łączący ich znaczenia.",
 l:"W odróżnieniu od zwykłego złożenia, jak zlewozmywak, w zbitce wyrazowej skleja się kawałki dwóch słów. Z żelaza i betonu powstał żelbet, z angielskich słów oznaczających dym i mgłę – smog, a z połączenia motoru i hotelu – motel. Takie słowa często rodzą się w reklamie, mediach i języku młodzieży, a niektóre na stałe wchodzą do słowników. Językoznawcy nazywają to zjawisko kontaminacją.",
 x:"Słowo żelbet to zbitka wyrazowa z żelaza i betonu.",
 f:"Angielską nazwę takich słów, portmanteau, spopularyzował Lewis Carroll w książce „Po drugiej stronie lustra”, gdzie Humpty Dumpty porównuje je do starej walizki z dwiema komorami.",
 js:"Słowo zrobione ze ściśniętych razem kawałków dwóch słów.",
 jl:"Niektóre słowa powstają tak, jakby dwa słowa wrzucić do miksera. Żelazo i beton dały słowo żelbet, a angielski dym i mgła – smog. Możesz wymyślić własne, na przykład łyżkowidelec, czyli łyżka i widelec naraz.",
 jx:"Na pikniku jedliśmy łyżkowidelcem i wymyśliłam dla niego własną zbitkę wyrazową."},
{id:"g_eponym",cat:"gen",t:"Eponim",
 s:"Wyraz utworzony od nazwiska lub imienia osoby, a także sama osoba, od której nazwy powstał.",
 l:"Wiele zwykłych słów było kiedyś czyimś nazwiskiem. Saksofon nazwano od belgijskiego wynalazcy Adolphe’a Saxa, mansardę od francuskiego architekta François Mansarta, a sylwestra od świętego Sylwestra, papieża wspominanego trzydziestego pierwszego grudnia. Eponimami są też jednostki w fizyce, jak wat i niuton. Z czasem ludzie zapominają o osobie i piszą takie słowa małą literą jak zwykłe wyrazy.",
 x:"Słowo sylwester to eponim, bo pochodzi od imienia świętego.",
 f:"Słowo bojkot pochodzi od nazwiska Charlesa Boycotta, zarządcy majątku w Irlandii, z którym w 1880 roku miejscowi ludzie zerwali wszelkie kontakty.",
 js:"Słowo, które pochodzi od czyjegoś imienia albo nazwiska.",
 jl:"Niektóre słowa wzięły się od prawdziwych ludzi. Saksofon nazwano od pana Saxa, który go wynalazł. Sylwester, czyli ostatnia noc roku, ma imię po świętym Sylwestrze. Takie słowa to eponimy.",
 jx:"Nie wiedziałam, że słowo sylwester pochodzi od imienia świętego."},
{id:"g_proverb",cat:"gen",t:"Przysłowie",
 s:"Krótkie, powszechnie znane powiedzenie, które wyraża życiową mądrość lub radę.",
 l:"Przysłowia przekazują doświadczenie w łatwej do zapamiętania formie, często z rymem, rytmem albo obrazowym porównaniem. Kto rano wstaje, temu Pan Bóg daje zachęca do wczesnego wstawania, a nie chwal dnia przed zachodem słońca ostrzega przed przedwczesną radością. W polszczyźnie jest wiele przysłów o pogodzie i porach roku. Niektóre sobie przeczą, jak co dwie głowy, to nie jedna oraz gdzie kucharek sześć, tam nie ma co jeść, co pokazuje, że to raczej wskazówki niż prawa.",
 x:"Babcia przypomniała mi przysłowie, że trening czyni mistrza, gdy narzekałem na lekcje pianina.",
 f:"Naukę o przysłowiach nazywa się paremiologią, od greckiego słowa paroimía, czyli przysłowie.",
 js:"Krótkie mądre powiedzenie, którego ludzie używają od dawna.",
 jl:"Przysłowie to małe powiedzenie pełne rad. Trening czyni mistrza znaczy, że im więcej ćwiczysz, tym lepiej ci idzie. Nie chwal dnia przed zachodem słońca znaczy, żeby nie cieszyć się za wcześnie. Dziadkowie często znają ich mnóstwo.",
 jx:"Pani powiedziała: lepiej późno niż wcale, kiedy w końcu oddałem zadanie."},
{id:"g_slang",cat:"gen",t:"Slang",
 s:"Bardzo nieformalne słowa i wyrażenia używane głównie w mowie, często przez określoną grupę, na przykład młodzież.",
 l:"Slang szybko się zmienia: słowa, które jednemu pokoleniu wydają się świeże, dla następnego brzmią staroświecko. Pomaga grupie poczuć wspólnotę i pokazuje, kto do niej należy, dlatego własne słownictwo tworzą nastolatki, kibice czy społeczności internetowe. Mówi się też o gwarze młodzieżowej albo środowiskowej. Część slangowych słów z czasem wchodzi do języka ogólnego, ale większość znika. Slang pasuje do swobodnej rozmowy, a w pismach urzędowych czy wypracowaniach się go unika.",
 x:"Rodzice nie rozumieją połowy slangu, który mój brat przynosi ze szkoły.",
 f:"Od 2016 roku Wydawnictwo Naukowe PWN organizuje plebiscyt Młodzieżowe Słowo Roku, w którym młodzi ludzie zgłaszają i wybierają ulubione słowa.",
 js:"Bardzo luźne słowa, których używają koledzy w rozmowie.",
 jl:"Slang to swobodny, zabawny sposób mówienia, którego używają przyjaciele między sobą. Każda paczka kolegów i każde pokolenie ma swoje ulubione słówka. Używa się ich w rozmowie, ale nie w wypracowaniu ani w liście do pani dyrektor.",
 jx:"Dziadek się zaśmiał, gdy użyłam nowego słowa ze slangu, którego nigdy nie słyszał."},
{id:"g_pl_sto_lat",cat:"gen",only:1,t:"Sto lat",
 s:"Tradycyjna polska piosenka z życzeniami długiego życia, śpiewana na urodzinach, imieninach i innych uroczystościach.",
 l:"Sto lat śpiewa się solenizantowi albo jubilatowi, często wtedy, gdy wnoszony jest tort lub gdy wszyscy wznoszą toast. Życzenie, by ktoś żył sto lat, jest w Polsce tak popularne, że samo zawołanie sto lat zastępuje często pełne życzenia. Piosenkę śpiewają też goście na weselach, a kibice na stadionach dla zasłużonych sportowców. Nie wiadomo dokładnie, kto ułożył jej słowa i melodię; uważa się ją za utwór ludowy.",
 x:"Kiedy dziadek zdmuchnął świeczki, cała rodzina zaśpiewała mu sto lat.",
 f:"Dla żartu goście czasem podbijają stawkę i śpiewają dwieście lat albo nawet tysiąc lat.",
 js:"Piosenka, którą Polacy śpiewają na urodzinach i imieninach.",
 jl:"Kiedy ktoś ma urodziny albo imieniny, wszyscy śpiewają mu sto lat. To znaczy, że życzymy mu, żeby żył bardzo, bardzo długo i był szczęśliwy. Często śpiewa się, gdy na stół wjeżdża tort ze świeczkami.",
 jx:"W klasie zaśpiewaliśmy Oli sto lat, bo miała urodziny."},
/* ---------- PSYCHOLOGIA (+6) ---------- */
{id:"p_boundaries",cat:"psy",t:"Granice osobiste",
 s:"Ustalone przez człowieka zasady tego, na co się zgadza, a na co nie w tym, jak traktują go inni – fizycznie i emocjonalnie.",
 l:"Granice mogą dotyczyć dotyku, przestrzeni osobistej, czasu, prywatności, rzeczy albo sposobu, w jaki ktoś się do nas odzywa. Zdrowe granice ułatwiają relacje, bo wszyscy wiedzą, co jest w porządku. Postawienie granicy może być proste, na przykład: potrzebuję teraz przerwy, albo: proszę, zapukaj, zanim wejdziesz. Granice różnych ludzi się różnią i mogą się zmieniać w zależności od sytuacji. Szanowanie cudzych granic jest tak samo ważne jak mówienie o własnych, a odmawianie jest w porządku.",
 x:"Powiedzenie współpracownikom, że w weekendy nie odpisuje na maile, było dla niej ważną granicą.",
 f:"Antropolog Edward T. Hall badał, w jakiej odległości od siebie ludzie lubią przebywać, i opisał to w 1966 roku w książce „Ukryty wymiar”.",
 js:"Twoje własne zasady, co jest dla ciebie w porządku, a co nie.",
 jl:"Każdy ma niewidzialne linie, które mówią, co jest dla niego miłe. Może nie lubisz łaskotek albo po szkole potrzebujesz chwili ciszy. To są twoje granice. Można powiedzieć stop albo nie, dziękuję, i miło jest słuchać, gdy mówią tak inni.",
 jx:"Powiedziałem kuzynowi, że nie lubię, gdy ktoś przytula mnie od tyłu, i uszanował moją granicę."},
{id:"p_emotion_regulation",cat:"psy",t:"Regulacja emocji",
 s:"Sposoby, w jakie ludzie zauważają, rozumieją swoje uczucia i radzą sobie z nimi, aby zareagować odpowiednio do sytuacji.",
 l:"Regulowanie emocji nie oznacza ich ukrywania ani tłumienia. Chodzi o to, by mieć sposoby radzenia sobie z silnymi uczuciami: zatrzymanie się, spokojny oddech, nazwanie uczucia, ruch, rozmowę z kimś bliskim czy przekierowanie uwagi. Te umiejętności rozwijają się w dzieciństwie i można się ich uczyć w każdym wieku. Niektórzy ludzie, w tym wiele osób autystycznych czy z ADHD, mogą przeżywać emocje intensywniej i potrzebują dopasowanych strategii. Często pierwszym krokiem jest koregulacja, czyli uspokajanie się przy wsparciu zaufanej osoby.",
 x:"Krótki spacer to jeden z jej najlepszych sposobów na regulację emocji, gdy czuje frustrację.",
 f:"Badanie zespołu Matthew Liebermana z Uniwersytetu Kalifornijskiego w Los Angeles, opublikowane w 2007 roku, wykazało, że nazywanie uczuć słowami może zmniejszać aktywność obszaru mózgu związanego z silnymi emocjami.",
 js:"Sposoby na radzenie sobie z wielkimi uczuciami, żeby nas nie przytłoczyły.",
 jl:"Czasem złość albo zmartwienie robią się naprawdę wielkie, jak fala. Regulacja emocji to szukanie sposobów, żeby na tej fali się utrzymać. Możesz powoli pooddychać, ścisnąć poduszkę, porysować albo powiedzieć dorosłemu, co czujesz. Każde uczucie jest w porządku, po prostu uczymy się, co pomaga.",
 jx:"Kiedy się zdenerwowałam, poszłam do kącika wyciszenia, który pomaga mi w regulacji emocji."},
{id:"p_maslow",cat:"psy",t:"Piramida potrzeb Maslowa",
 s:"Teoria psychologa Abrahama Maslowa, która układa ludzkie potrzeby w poziomy – od podstawowych potrzeb przetrwania po rozwój osobisty.",
 l:"Maslow uważał, że człowieka motywują najpierw potrzeby fizjologiczne, takie jak jedzenie, woda i sen, potem potrzeba bezpieczeństwa, następnie miłości i przynależności, uznania, a na końcu samorealizacji, czyli stawania się w pełni sobą. Teorię często przedstawia się jako piramidę. Uczy się o niej w szkołach, na studiach pielęgniarskich i w biznesie, ale badacze zwracają uwagę, że ludzie nie zawsze zaspokajają potrzeby w ścisłej kolejności i że w różnych kulturach potrzeby bywają różne.",
 x:"Nauczycielka użyła piramidy Maslowa, żeby wyjaśnić, dlaczego głodnym uczniom trudno się skupić.",
 f:"Maslow opisał swoją teorię w artykule w 1943 roku, ale słynny rysunek piramidy stworzyli później inni autorzy, a nie on sam.",
 js:"Pomysł, że ludzie najpierw potrzebują jedzenia i bezpieczeństwa, potem miłości, a potem szans na rozwój.",
 jl:"Naukowiec Abraham Maslow wymyślił, jak ułożyć to, czego ludzie potrzebują. Najpierw jedzenie, woda, sen i bezpieczny dom. Potem przyjaciele i rodzina, którzy nas kochają. Gdy to mamy, możemy rosnąć, uczyć się i robić to, co kochamy.",
 jx:"Narysowaliśmy w klasie piramidę Maslowa i na dole wpisaliśmy jedzenie i sen."},
{id:"p_framing_effect",cat:"psy",t:"Efekt ramowania (efekt ujęcia)",
 s:"Skłonność do podejmowania różnych decyzji w zależności od tego, jak przedstawiono te same informacje.",
 l:"Egzamin opisany jako zdawany przez osiemdziesiąt procent uczniów wydaje się łatwiejszy niż taki, którego nie zdaje dwadzieścia procent, choć to dokładnie to samo. Podobnie leczenie, po którym przeżywa dziewięćdziesiąt procent pacjentów, wydaje się lepsze niż takie, po którym umiera dziesięć procent. Ramowanie działa, bo na zyski i straty reagujemy emocjonalnie, a nie tylko na liczby. Korzystają z niego reklamodawcy, politycy i kampanie zdrowotne, więc przed decyzją warto przedstawić sobie informację odwrotnie.",
 x:"Przez efekt ramowania oferta brzmiała lepiej: oszczędzasz dwadzieścia procent zamiast płacisz osiemdziesiąt procent.",
 f:"Psychologowie Amos Tversky i Daniel Kahneman opisali to zjawisko w słynnym artykule z 1981 roku; Kahneman otrzymał w 2002 roku Nagrodę Nobla z ekonomii.",
 js:"Gdy to, jak coś powiemy, zmienia nasz wybór.",
 jl:"Wyobraź sobie, że o tej samej szklance ktoś mówi: do połowy pełna, a ktoś inny: do połowy pusta. To znaczy dokładnie to samo, ale brzmi inaczej. Sposób opisania czegoś może zmienić to, co ludzie czują. To efekt ramowania.",
 jx:"Sklep napisał: zostały tylko dwie sztuki, żebyśmy się pospieszyli, i to trochę efekt ramowania."},
{id:"p_active_listening",cat:"psy",t:"Aktywne słuchanie",
 s:"Słuchanie z pełną uwagą, połączone ze staraniem, by zrozumieć rozmówcę, i pokazaniem mu, że się go zrozumiało.",
 l:"Aktywne słuchanie to coś więcej niż milczenie, gdy ktoś mówi. Słuchający skupia się na rozmówcy, nie przerywa i nie układa w myślach odpowiedzi, zadaje pytania otwarte i streszcza własnymi słowami, co usłyszał, na przykład: czyli poczułaś się pominięta, kiedy to się stało. Zwraca uwagę nie tylko na fakty, ale i na uczucia. Korzystają z niego psychologowie, nauczyciele, lekarze i mediatorzy, a w przyjaźni i rodzinie też bardzo pomaga. Osoby, dla których kontakt wzrokowy jest niekomfortowy, mogą słuchać aktywnie na inne sposoby.",
 x:"Dzięki aktywnemu słuchaniu kierowniczka zrozumiała, co naprawdę martwi jej zespół.",
 f:"Pojęcie aktywnego słuchania wprowadzili psychologowie Carl Rogers i Richard Farson w artykule z 1957 roku.",
 js:"Uważne słuchanie, które pokazuje, że naprawdę rozumiesz.",
 jl:"Aktywne słuchanie to słuchanie całą swoją uwagą. Pozwalasz koledze skończyć, nie wtrącasz się, a potem mówisz, co usłyszałeś, na przykład: czyli było ci smutno, bo gra się skończyła. Dzięki temu ludzie czują, że ktoś ich naprawdę słucha.",
 jx:"Kiedy przyjaciółka opowiadała mi o zgubionym kocie, ćwiczyłam aktywne słuchanie."},
{id:"p_delayed_gratification",cat:"psy",t:"Odraczanie gratyfikacji",
 s:"Wybieranie większej lub lepszej nagrody później zamiast mniejszej od razu.",
 l:"Odkładanie kieszonkowego na coś wyjątkowego albo odrobienie lekcji przed zabawą to codzienne przykłady. Zdolność czekania zależy od wielu rzeczy: wieku, zmęczenia, stresu i tego, czy ufamy, że obiecana nagroda naprawdę nadejdzie. Czekanie ułatwiają sposoby takie jak zajęcie się czymś innym, schowanie pokusy z oczu czy ułożenie planu. To umiejętność, która się rozwija, a nie stała cecha, a w przypadku osób z ADHD duże znaczenie mają otoczenie i wsparcie.",
 x:"Odkładanie przez trzy miesiące na rower było prawdziwym ćwiczeniem w odraczaniu gratyfikacji.",
 f:"W słynnym teście pianki przeprowadzonym na Uniwersytecie Stanforda około 1970 roku Walter Mischel pozwalał dzieciom wybrać jeden smakołyk od razu albo dwa później; większe badanie z 2018 roku wykazało, że związek z późniejszymi sukcesami jest dużo słabszy, niż sądzono.",
 js:"Czekanie na coś lepszego zamiast brania czegoś mniejszego od razu.",
 jl:"Wyobraź sobie, że możesz dostać jedną naklejkę teraz albo trzy jutro. Czekanie na trzy to odraczanie gratyfikacji. Czekanie bywa trudne. Pomaga schowanie nagrody z oczu, zabawa albo myślenie o czymś innym.",
 jx:"Przez kilka tygodni odkładałem kieszonkowe zamiast kupować słodycze i kupiłem nową książkę."}
]);
